   "chapters": {
    "status": "complete",
    "clock": "upload",
    "format": "captions",
    "writtenAt": "2026-09-02T00:34:09.377Z",
    "list": [
     {
      "start": "00:03:15",
      "seconds": 195,
      "title": "Cold open montage and a bumpy first launch",
      "gist": "A montage of designers on AI experimentation leads into the hosts greeting viewers after a chaotic setup.",
      "quote": "Show up, try things, be curious"
     },
     {
      "start": "00:07:34",
      "seconds": 454,
      "title": "Why launch a live design show",
      "gist": "The hosts explain what a live stream offers over the polished podcast and what they hope it becomes.",
      "quote": "I really follow what brings me life"
     },
     {
      "start": "00:14:08",
      "seconds": 848,
      "title": "Daily driver models and going local",
      "gist": "The hosts compare their daily driver models and weigh deleted projects and running local models.",
      "quote": "What's your daily driver, man?"
     },
     {
      "start": "00:20:10",
      "seconds": 1210,
      "title": "Voice interfaces take over daily life",
      "gist": "The hosts trade stories of voice mode helping in the kitchen, in parking lots, and coaching a game.",
      "quote": "GPT Live came out and so I've been messing around with that"
     },
     {
      "start": "00:31:15",
      "seconds": 1875,
      "title": "Cursor's comeback and the great bundling",
      "gist": "The hosts discuss Cursor's rise, big designer hires, and how every tool now builds everything.",
      "quote": "Can we call cursor a startup anymore"
     },
     {
      "start": "00:39:56",
      "seconds": 2396,
      "title": "The Gal retirement debate and an AI style test",
      "gist": "The hosts defend a famous designer's retirement post and test an AI recreation of his motion style.",
      "quote": "I want to hear your take"
     },
     {
      "start": "00:57:36",
      "seconds": 3456,
      "title": "Burnout, token FOMO, and panic attacks",
      "gist": "The hosts open up about panic attacks, token limit pressure, and the exhaustion of constant multitasking.",
      "quote": "This past weekend, I had a panic attack"
     },
     {
      "start": "01:04:21",
      "seconds": 3861,
      "title": "Rebranding Dive with mood boards and a playable radio",
      "gist": "The hosts walk through mood boarding with image tools and the interactive radio site with sound design.",
      "quote": "we've been working on some fun stuff"
     },
     {
      "start": "01:25:18",
      "seconds": 5118,
      "title": "A whirlwind brand sprint and audience voting",
      "gist": "The hosts tour FS's rapid brand explorations and ask viewers to vote between sticker and paper styles.",
      "quote": "we had a kickoff call with FS on Monday"
     },
     {
      "start": "01:53:27",
      "seconds": 6807,
      "title": "One-up finds, listener questions, and signing off",
      "gist": "The hosts share a community-built interactive television, a mixed media tool, answer questions, and wrap up.",
      "quote": "We didn't even get to our oneup"
     }
    ]
   }
